# Documentação própria do projeto.
doc=f'''<div class="documentation-body"><section id="doc-visao"><h3>Visão geral</h3><p>O CashFlow Intelligence transforma fontes financeiras dispersas em uma camada analítica rastreável para decisões operacionais e executivas. A solução trabalha com dados sintéticos e demonstra arquitetura, automação, conciliação, qualidade e visualização.</p></section><section id="doc-fontes"><h3>Fontes e escopo</h3><p>O processo recebe seis fontes: contas a receber, contas a pagar, extrato bancário, orçamento mensal, cadastro de entidades e centros de custo. Os CSVs representam exportações brutas que poderiam ser obtidas diretamente de bancos de dados.</p><div class="doc-grid"><article><b>Entradas</b><code>01_contas_receber</code><code>02_contas_pagar</code><code>03_extrato_bancario</code><code>04_orcamento_mensal</code><code>05_cadastro_entidades</code><code>06_centros_de_custo</code></article><article><b>Saídas analíticas</b><code>FATO_Financeira</code><code>FATO_Orcamento</code><code>DIM_Entidades</code><code>DIM_Centros_Custo</code><code>DIM_Categorias</code><code>CONCILIACAO</code><code>LOG_Qualidade</code><code>RESUMO_Execucao</code></article></div></section><section id="doc-codigo"><div class="doc-heading"><div><p class="eyebrow">IMPLEMENTAÇÃO</p><h3>Código Apps Script</h3></div><button class="copy-code" data-copy-code>Copiar código</button></div><p>O script preserva as abas brutas, padroniza campos, remove duplicidades, cria IDs determinísticos, executa conciliação estrita ou provável e registra problemas de qualidade. O tratamento pode ser iniciado pelo menu da planilha ou por acionador temporal.</p><details class="code-disclosure"><summary>Visualizar código completo</summary><pre><code id="cashflow-code">Carregando código…</code></pre></details><p class="technical-note"><b>Comportamento registrado:</b> a função <code>recriarConciliacao()</code> chama atualmente o tratamento completo. O acionador de 15 minutos é configurado no ambiente do Apps Script.</p></section><section id="doc-modelo"><h3>Modelo de dados</h3><div class="model-flow"><span>Fontes brutas</span><i>→</i><span>Tabelas tratadas</span><i>→</i><span>Fatos e dimensões</span><i>→</i><span>Conciliação e qualidade</span><i>→</i><span>DataStudio</span></div><p>A <code>FATO_Financeira</code> consolida títulos e movimentos; a <code>FATO_Orcamento</code> suporta orçamento versus realizado; dimensões padronizam entidades, centros e categorias; <code>CONCILIACAO</code> guarda vínculos e confiança; e <code>LOG_Qualidade</code> preserva rastreabilidade.</p></section><section id="doc-paginas"><h3>Jornada analítica</h3><ol><li>Visão Executiva</li><li>Fluxo de Caixa</li><li>Contas a Receber</li><li>Contas a Pagar</li><li>Orçamento × Realizado</li><li>Conciliação e Qualidade</li></ol></section><section id="doc-links"><h3>Links do código e da base</h3><div class="doc-links"><a class="secondary" href="{base}" target="_blank" rel="noopener noreferrer">Abrir base no Google Sheets ↗</a><a class="secondary" href="../content/projects/cashflow-intelligence/CashFlow.gs" download>Baixar código Apps Script ↓</a></div></section><section id="doc-validacoes"><h3>Validações e limitações</h3><ul class="check-list"><li>Entradas menos saídas conferem com o saldo líquido.</li><li>Filtros afetam os visuais esperados.</li><li>Entradas e saídas não são duplicadas.</li><li>Combinações mantêm a granularidade correta.</li><li>Matches prováveis permanecem revisáveis.</li><li>Registros podem ser rastreados até a fonte.</li><li>Dashboard funciona em tela de notebook.</li></ul><div class="data-note"><b>Dados 100% fictícios</b><p>Indicadores, documentos e transações foram criados para demonstração. A atualização ocorre em janelas de 15 minutos; não se trata de processamento em tempo real. A conciliação provável exige revisão e a ausência de saldo inicial limita determinadas leituras de posição.</p></div></section></div>'''
(proj/'documentation.html').write_text(doc,encoding='utf-8')
# Renderer do projeto e card único.
app=root/'app.js';s=app.read_text(encoding='utf-8')
card="""function projectCard(p){return `<article class=\"project-card project-card-${slug(p.category)}\" data-id=\"${p.id}\" data-category=\"${p.category}\"><div class=\"project-cover\"><img src=\"${BASE}/content/projects/${p.id}/${p.cover}\" alt=\"Capa do projeto ${p.title}\"></div><div class=\"project-summary\"><div class=\"project-meta\"><span>${p.category} • ${p.year}</span><span class=\"status-badge status-${slug(p.status)}\">${p.status}</span></div><h2>${p.title}</h2><p>${p.summary}</p><div class=\"card-actions single\"><a class=\"project-link\" href=\"${BASE}/projeto/index.html?id=${p.id}\">${tx('Ver case completo','View full case')} <span>→</span></a></div></div></article>`}\n"""
a=s.index('function projectCard(');b=s.index('function modal',a);s=s[:a]+card+s[b:]
detail=r'''async function loadCashflowDocumentation(){const host=q('#cashflow-documentation');if(!host)return;try{host.innerHTML=await fetch(`${BASE}/content/projects/cashflow-intelligence/documentation.html`).then(r=>r.text());const code=await fetch(`${BASE}/content/projects/cashflow-intelligence/CashFlow.gs`).then(r=>r.text()),target=q('#cashflow-code');if(target)target.textContent=code;const copy=q('[data-copy-code]');if(copy)copy.addEventListener('click',async()=>{await navigator.clipboard.writeText(code);copy.textContent=tx('Código copiado','Code copied');setTimeout(()=>copy.textContent=tx('Copiar código','Copy code'),1800)})}catch{host.innerHTML='<p>Não foi possível carregar a documentação.</p>'}const links=qa('.case-index a'),sections=links.map(a=>q(a.getAttribute('href'))).filter(Boolean);links.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();q(a.getAttribute('href'))?.scrollIntoView({behavior:'smooth',block:'start'})}));if('IntersectionObserver'in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}}),{rootMargin:'-24% 0px -66% 0px'});sections.forEach(x=>io.observe(x))}}
async function detail(){const el=q('#project-detail');if(!el)return;const id=new URLSearchParams(location.search).get('id'),data=await projects(),p=data.find(x=>x.id===id);if(!p){el.innerHTML='<section class="page-hero"><h1>Projeto não encontrado.</h1></section>';return}const points=p.solutionPoints||[p.solution],stack=p.stackGroups||[],dashboard=p.demo?.embedUrl,external=p.demo?.externalUrl||dashboard;el.innerHTML=`<article class="project-case cashflow-case"><div class="case-layout"><aside class="case-index" aria-label="Navegação do projeto"><span>${tx('Neste projeto','In this project')}</span><a href="#introducao" class="active">${tx('Introdução','Introduction')}</a><a href="#sobre-projeto">${tx('Sobre o projeto','About')}</a><a href="#stack-projeto">Stack</a><a href="#dashboard-interativo">Dashboard</a><a href="#arquitetura">${tx('Arquitetura','Architecture')}</a><a href="#links-projeto">Links</a><a href="#documentacao">${tx('Documentação','Documentation')}</a></aside><div class="case-content"><section id="introducao" class="case-intro"><a class="back-button" href="${BASE}/projetos/index.html">← ${tx('Voltar aos projetos','Back to projects')}</a><p class="eyebrow">${p.projectType} • ${p.year}</p><div class="case-title-line"><h1>${p.title}</h1><span class="status-badge">${p.status}</span></div><p class="lede">${p.summary}</p></section><section id="sobre-projeto" class="case-section"><p class="eyebrow">${tx('CONTEXTO','CONTEXT')}</p><h2>${tx('Sobre o projeto','About the project')}</h2><div class="case-grid"><section><small>${tx('PROBLEMA','PROBLEM')}</small><p>${p.problem}</p></section><section><small>${tx('MEU PAPEL','MY ROLE')}</small><p>${p.role}</p></section><section class="wide"><small>${tx('SOLUÇÃO','SOLUTION')}</small><ul>${points.map(x=>`<li>${x}</li>`).join('')}</ul></section><section class="wide"><small>${tx('ENTREGAS','DELIVERABLES')}</small><ul>${p.results.map(x=>`<li>${x}</li>`).join('')}</ul></section></div></section><section id="stack-projeto" class="case-section"><p class="eyebrow">STACK</p><h2>${tx('Stack do projeto','Project stack')}</h2><div class="stack-groups">${stack.map(g=>`<div class="stack-group"><small>${g.label}</small><div class="tags">${g.items.map(i=>`<span>${i}</span>`).join('')}</div></div>`).join('')}</div></section><section id="dashboard-interativo" class="case-section"><p class="eyebrow">${tx('DASHBOARD INTERATIVO','INTERACTIVE DASHBOARD')}</p><h2>${tx('Explore os indicadores','Explore the indicators')}</h2><p class="section-copy">${tx('Navegue pelas páginas e utilize os filtros para analisar caixa, orçamento, atrasos, conciliação e qualidade.','Navigate the pages and use filters to analyze cash, budget, delays, reconciliation and quality.')}</p><div class="datastudio-frame"><div class="dashboard-loading">${tx('Carregando dashboard…','Loading dashboard…')}</div><iframe src="${dashboard}" title="CashFlow Intelligence — Dashboard" loading="lazy" allowfullscreen sandbox="allow-storage-access-by-user-activation allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"></iframe></div></section><section id="arquitetura" class="case-section"><p class="eyebrow">${tx('FLUXO TÉCNICO','TECHNICAL FLOW')}</p><h2>${tx('Arquitetura e processamento','Architecture and processing')}</h2><div class="architecture-flow"><span>CSV / Banco de dados</span><i>→</i><span>Google Sheets</span><i>→</i><span>Apps Script</span><i>→</i><span>Fatos, dimensões e qualidade</span><i>→</i><span>DataStudio</span></div><div class="automation-grid"><article><b>${tx('Automático','Automated')}</b><p>${tx('Tratamento por acionador a cada 15 minutos, alinhado à atualização do dashboard.','Processing through a 15-minute trigger aligned with dashboard refresh.')}</p></article><article><b>${tx('Manual','Manual')}</b><p>${tx('Menu na planilha com retorno de conclusão para análises rápidas.','Spreadsheet menu with completion feedback for quick analyses.')}</p></article></div></section><section id="links-projeto" class="case-section project-dashboard-link"><p class="eyebrow">LINK</p><h2>${tx('Links do projeto','Project links')}</h2><a class="primary" href="${external}" target="_blank" rel="noopener noreferrer">${tx('Abrir dashboard no DataStudio','Open dashboard in DataStudio')} ↗</a></section><section id="documentacao" class="case-section documentation-section"><p class="eyebrow">${tx('DETALHAMENTO TÉCNICO','TECHNICAL DETAILS')}</p><h2>${tx('Documentação completa do projeto','Complete project documentation')}</h2><div id="cashflow-documentation"><p>${tx('Carregando documentação…','Loading documentation…')}</p></div></section></div></div></article>`;await loadCashflowDocumentation()}
'''
a=s.index('async function detail(');b=s.index('async function career',a);s=s[:a]+detail+s[b:]
# Clique reforça pulsos da rede interna, mantendo baixa opacidade.
s=s.replace("addEventListener('pointerleave',()=>pt={x:-999,y:-999});function draw", "addEventListener('pointerleave',()=>pt={x:-999,y:-999});addEventListener('click',e=>{pt.x=e.clientX;pt.y=e.clientY;launch(8)});function draw")
app.write_text(s,encoding='utf-8')
