s+='''\n\n/* FINAL6 — case CashFlow e template de projetos de dados */\n.card-actions.single{grid-template-columns:1fr}.card-actions.single .project-link{width:100%}.cashflow-case{padding:42px 0 110px}.case-layout{display:grid;grid-template-columns:190px minmax(0,1fr);gap:42px}.case-index{position:sticky;top:100px;align-self:start;display:grid;gap:5px;padding:16px;border:1px solid var(--line);border-radius:14px;background:color-mix(in srgb,var(--white) 88%,transparent);backdrop-filter:blur(16px)}.case-index span{font-size:11px;font-weight:800;letter-spacing:.12em;color:var(--muted);padding:6px 10px 10px}.case-index a{padding:9px 10px;border-radius:8px;color:var(--muted);text-decoration:none;font-size:13px}.case-index a:hover,.case-index a.active{background:var(--accent-soft);color:var(--accent);font-weight:700}.case-content{min-width:0}.case-section,.case-intro{scroll-margin-top:98px;padding:58px 0;border-bottom:1px solid var(--line)}.case-intro{padding-top:0}.back-button{display:inline-flex;align-items:center;min-height:42px;padding:0 14px;margin-bottom:30px;border:1px solid var(--line);border-radius:9px;background:var(--white);color:var(--ink);font-weight:700;text-decoration:none}.back-button:hover{border-color:var(--accent);color:var(--accent);transform:translateY(-1px)}.case-title-line{display:flex;align-items:flex-end;justify-content:space-between;gap:24px}.case-title-line h1{font-size:clamp(44px,6vw,78px)}.case-title-line .status-badge{flex:none;margin-bottom:9px;padding:8px 12px;border-radius:999px;background:var(--accent-soft);color:var(--accent);font-size:12px;font-weight:800}.cashflow-case .case-grid{margin-bottom:0}.cashflow-case .case-grid .wide{grid-column:1/-1}.cashflow-case .case-grid p,.cashflow-case .case-grid li,.section-copy{color:var(--muted)}.cashflow-case .stack-groups{margin-top:28px}.datastudio-frame{margin-top:26px}.architecture-flow,.model-flow{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:28px 0}.architecture-flow span,.model-flow span{padding:12px 14px;border:1px solid var(--line);border-radius:9px;background:var(--white);font-weight:700;font-size:13px}.architecture-flow i,.model-flow i{color:var(--accent);font-style:normal;font-weight:900}.automation-grid,.doc-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.automation-grid article,.doc-grid article{padding:20px;border:1px solid var(--line);border-radius:11px;background:var(--white)}.automation-grid p{margin-bottom:0;color:var(--muted)}.project-dashboard-link{padding-bottom:78px}.documentation-section{border-bottom:0;padding-bottom:70px}.documentation-body>section{padding:34px 0;border-bottom:1px solid var(--line)}.documentation-body h3{font-size:26px;margin:0 0 14px}.documentation-body p,.documentation-body li{color:var(--muted)}.doc-grid article{display:grid;gap:7px}.doc-grid code{display:block;padding:7px 9px;border-radius:6px;background:var(--paper);font-size:12px}.doc-heading{display:flex;align-items:end;justify-content:space-between;gap:18px}.copy-code{min-height:42px;padding:0 14px;border:1px solid var(--line);border-radius:8px;background:var(--white);color:var(--ink);font-weight:700;cursor:pointer}.code-disclosure{margin-top:20px;border:1px solid var(--line);border-radius:12px;background:#0b1115;overflow:hidden}.code-disclosure summary{padding:16px;color:#e8f1f8;font-weight:700;cursor:pointer}.code-disclosure pre{max-height:620px;overflow:auto;margin:0;padding:20px;border-top:1px solid rgba(255,255,255,.12)}.code-disclosure code{color:#c8e2f8;font:12px/1.65 Consolas,monospace;white-space:pre}.technical-note,.data-note{padding:18px;border-left:3px solid var(--accent);border-radius:0 9px 9px 0;background:var(--accent-soft)}.doc-links{display:flex;gap:10px;flex-wrap:wrap}.check-list{columns:2;column-gap:36px}.check-list li{break-inside:avoid;margin-bottom:9px}body[data-page]:not([data-page="inicio"]) #starfield{opacity:.42!important;filter:saturate(1)!important}body[data-page]:not([data-page="inicio"]){background-image:radial-gradient(circle at 18% 20%,rgba(var(--star),.08),transparent 33%),radial-gradient(circle at 82% 70%,rgba(var(--star),.06),transparent 35%)}@media(max-width:900px){.case-layout{grid-template-columns:1fr}.case-index{position:sticky;top:78px;z-index:30;display:flex;overflow:auto;white-space:nowrap;margin:0 -20px;padding:10px 20px;border-width:1px 0;border-radius:0}.case-index span{display:none}.case-index a{flex:none}.case-title-line{align-items:start;flex-direction:column}.case-title-line .status-badge{margin:0}.check-list{columns:1}}@media(max-width:650px){.cashflow-case{padding-top:24px}.case-section{padding:46px 0}.automation-grid,.doc-grid{grid-template-columns:1fr}.architecture-flow,.model-flow{display:grid;grid-template-columns:1fr}.architecture-flow i,.model-flow i{transform:rotate(90deg);justify-self:center}.doc-heading{align-items:start;flex-direction:column}.copy-code{width:100%}.project-dashboard-link{padding-bottom:68px}}\n'''
